effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     #define S(a, b, t) smoothstep(a, b, t)

     float distLine(vec2 p, vec2 a, vec2 b){
     	vec2 pa = p - a;
         vec2 ba = b - a;
         float t = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
         return length(pa - ba*t);
     }

     float line(vec2 p, vec2 a, vec2 b){
     	float d = distLine(p, a, b);
         float m = S(0.03, 0.01, d);
         float d2 =  length(a - b);
         m *= S(1.2, 0.8, d2) * 0.5 + S(0.05, 0.03, abs(d2 - 0.75));
         return m;
     }

     float distTriangle(in vec2 p, in vec2 p0, in vec2 p1, in vec2 p2 )
     {
     	vec2 e0 = p1 - p0;
     	vec2 e1 = p2 - p1;
     	vec2 e2 = p0 - p2;

     	vec2 v0 = p - p0;
     	vec2 v1 = p - p1;
     	vec2 v2 = p - p2;

     	vec2 pq0 = v0 - e0*clamp( dot(v0,e0)/dot(e0,e0), 0.0, 1.0 );
     	vec2 pq1 = v1 - e1*clamp( dot(v1,e1)/dot(e1,e1), 0.0, 1.0 );
     	vec2 pq2 = v2 - e2*clamp( dot(v2,e2)/dot(e2,e2), 0.0, 1.0 );

         float s = sign( e0.x*e2.y - e0.y*e2.x );
         vec2 d = min( min( vec2( dot( pq0, pq0 ), s*(v0.x*e0.y-v0.y*e0.x) ),
                            vec2( dot( pq1, pq1 ), s*(v1.x*e1.y-v1.y*e1.x) )),
                            vec2( dot( pq2, pq2 ), s*(v2.x*e2.y-v2.y*e2.x) ));

     	return -sqrt(d.x)*sign(d.y);
     }

     float triangle(vec2 p, vec2 a, vec2 b, vec2 c){
     	float d = distTriangle(p, a, b, c);
         float m = S(0.03, 0.01, d);
         float d2 =  length(a - b);
         m *= S(1.2, 0.8, d2) * 0.5 + S(0.05, 0.03, abs(d2 - 0.75));
         return m;
     }

     float N21(vec2 p){
     	p = fract(p * vec2(233.34, 851.73));
         p += dot(p, p + 23.45);
         return fract(p.x * p.y);
     }

     vec2 N22(vec2 p){
     	float n = N21(p);
         return vec2(n, N21(p + n));
     }

     vec2 getPos(vec2 id, vec2 offset){
         float FEVO = autoe? XXA+(acTime*0.5) : XXA;
         vec2 n = N22(id + offset) * FEVO;
         return offset + sin(n) * 0.4;
     }

     float layer(vec2 uv){
     	vec2 gv = fract(uv) - 0.5;
         vec2 id = floor(uv);

         vec2 p[9];
         int i = 0;
         for(float y = -1.0; y <= 1.0; y++){
         	for(float x = -1.0; x <= 1.0; x++){
             	p[i++] = getPos(id, vec2(x, y));
         	}    
         }


         float t = autob? (XXB+acTime*0.5) * 10.0 : XXB * 10.0;
         float m = 0.0;
         for(int i = 0; i < 9; i++){
         	m += line(gv, p[4], p[i]);

             vec2 j = (p[i] - gv) * 20.0;
             float sparkle = 1.0 / dot(j, j);

             m += sparkle * (sin(t + fract(p[i].x) * 10.0) * 0.5 + 0.5);

             for(int yi= i + 1; yi < 9; yi++){
         		for(int zi= yi + 1; zi < 9; zi++){

                     float len1 = abs(length(p[i] - p[yi]));
                     float len2 = abs(length(p[yi] - p[zi]));
                     float len3 = abs(length(p[i] - p[zi]));

                     if((len1 + len2 + len3) < 2.8){
                     	m += triangle(gv, p[i], p[yi], p[zi]) * 0.8;
                     }
         		}
         	}
         }
         m += line(gv, p[1], p[3]);
         m += line(gv, p[1], p[5]);
         m += line(gv, p[7], p[3]);
         m += line(gv, p[7], p[5]);

         return m;
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     // vec2 TanRyu;
     // TanRyu = acScreenNorm; 

     vec2 TanRyu;
     TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     TanRyu.y*=acLayerSize.y/acLayerSize.x;
     TanRyu /= scale;
     float ROTATE = autor? angle+(acTime*2.5) : angle;
     TanRyu *= rot2m((0.0+ROTATE)*0.0174533);
     TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     TanRyu /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

         vec2 uv = TanRyu;
         // vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

         float m = 0.0;
         float mm = 0.0;
         float t = autop? (XXC+acTime*0.5) * 0.1 : XXC * 0.1;

         float s = sin(t);
         float c = cos(t);
         mat2 rot = mat2(c, -s, s, c);
         // uv *= rot;

         for(float i = 0.0; i < 1.0; i += 16.0){
         // for(float i = 0.0; i < 1.0; i += 1.0 / 4.0){
             float z = fract(i + t);
             float size = mix(10.0, 0.5, z);
             float fade = S(0.0, 0.5, z) * S(1.0, 0.8, z);

             m += layer(uv * size + i * 20.0) * fade;
             mm += layer(uv * size + i * 20.0);
         }


         vec3 base = sin(t * 5.0 * vec3(0.345, 0.456, 0.567)) * 0.4 + 0.6;
         // vec3 bases = vec3(1.0, 1.0, 1.0);
         vec3 col = autos?m * base : mm * color2.rgb;
         // vec3 col = autos?m * base : mm * bases;
         // col *= color2.rgb;

         fragColor = vec4(col,0.0);
         if(invert) { fragColor = 1.-fragColor; }

 	vec4 factor = newLayer(color1,fragColor);
 	// vec4 factorx = newLayer(color1,fragColor*(hardness-0.4));

     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= 1.0;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         // resultfinal = max(factor, texColor) * texColor.a; }
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
       // else if( blendMode==3 ) { factorx *= 1.0; 
         // resultfinal = (newLayer(texColor, factorx) * 1.0) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
